/* Linked against the actual prebuilt Zig number object and selected C runtime. */
extern myl_block *myl_core_format_float(double value, uint64_t word);
extern myl_block *myl_core_format_number(uint64_t value, uint64_t word);
extern myl_block *myl_core_format_text(const myl_block *source, uint64_t word);
/* No guest callback is generated by this scalar-only standalone probe. */
myl_block *myl_core_task_call(void *run, myl_block *env) { (void)run; (void)env; abort(); }
extern double myl_core_round_float(double value, int64_t digits);
#define CHECK(expression) do { if (!(expression)) { fputs(#expression "\n", stderr); return 1; } } while (0)

static uint64_t spec(uint32_t fill, unsigned kind, unsigned family, unsigned precision, unsigned width) {
    return fill | (UINT64_C(3) << 21) | ((uint64_t)kind << 30) | ((uint64_t)family << 34) |
           (UINT64_C(1) << 36) | ((uint64_t)precision << 37) | ((uint64_t)width << 49);
}

static void drop(myl_block *text) {
#ifdef MYL_ZERO_RC
    myl_core_drop_owned(text);
#else
    myl_core_release(text);
#endif
}

int main(void) {
    const char *answers[] = {"ééé1.2éééé", "ééé1.25ééé", "éé1.250ééé"};
    for (unsigned precision = 1; precision <= 3; precision++) {
        volatile double input = 1.25;
        myl_block *text = myl_core_format_float(input, spec(0xe9, 9, 2, precision, 10));
        CHECK(kind_of(text) == MYL_KIND_STR);
        CHECK((text->kind & MYL_TEXT_ASCII) == 0);
        CHECK(text->len == (int64_t)strlen(answers[precision - 1]));
        CHECK(memcmp(block_data(text), answers[precision - 1], (size_t)text->len) == 0);
        CHECK(myl_core_str_chars(text) == 10);
        CHECK(myl_core_str_offset(text, 1) == 2);
        myl_block *saved = myl_core_owned_octets_copy(text);
        drop(text);
        CHECK(myl_core_str_chars(saved) == 10);
        drop(saved);
    }
    myl_block *integer = myl_core_format_number(42, spec(0xe9, 1, 0, 0, 6) & ~(UINT64_C(1) << 36));
    CHECK(integer->len == 10 && myl_core_str_chars(integer) == 6);
    CHECK(memcmp(block_data(integer), "éé42éé", 10) == 0);
    drop(integer);
    myl_block *input = str_from("\xce\xbbx", 3);
    myl_block *output = myl_core_format_text(input, spec(0xe9, 14, 3, 1, 5));
    drop(input);
    CHECK(output->len == 10 && myl_core_str_chars(output) == 5);
    CHECK(memcmp(block_data(output), "ééλéé", 10) == 0);
    drop(output);
    CHECK(myl_core_round_float(1.25, 1) == 1.3);
    CHECK(myl_core_round_float(1.75, 1) == 1.8);
    CHECK(live_count() == 0);
    return 0;
}
